import hashlib
import hmac
import os
import time
import threading
from flask import Flask, request, jsonify, make_response

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())

# Thread-safe session store
class SessionStore:
    def __init__(self):
        self._lock = threading.Lock()
        self._sessions = {}
        self._rotation_map = {}  # old_id -> new_id for grace period

    def create(self, user_id, role='user'):
        session_id = hashlib.sha256(os.urandom(32)).hexdigest()
        with self._lock:
            self._sessions[session_id] = {
                'user_id': user_id,
                'role': role,
                'created_at': time.time(),
                'last_access': time.time()
            }
        return session_id

    def get(self, session_id):
        with self._lock:
            # Check if this is a rotated session (grace period lookup)
            if session_id in self._rotation_map:
                new_id = self._rotation_map[session_id]
                return self._sessions.get(new_id)
            return self._sessions.get(session_id)

    def rotate(self, old_session_id):
        """Rotate session ID for security. Returns new session ID.
        Old ID enters grace period for in-flight requests."""
        with self._lock:
            if old_session_id not in self._sessions:
                return None
            # Generate new session ID
            new_session_id = hashlib.sha256(os.urandom(32)).hexdigest()
            # Copy session data to new ID
            session_data = self._sessions[old_session_id]
            self._sessions[new_session_id] = session_data
            # Add to rotation map for grace period
            self._rotation_map[old_session_id] = new_session_id
            # Schedule cleanup of old mapping (grace period: 30s)
            self._schedule_cleanup(old_session_id)
            return new_session_id

    def _schedule_cleanup(self, old_id):
        def cleanup():
            with self._lock:
                self._rotation_map.pop(old_id, None)
                self._sessions.pop(old_id, None)
        timer = threading.Timer(30.0, cleanup)
        timer.daemon = True
        timer.start()

    def invalidate(self, session_id):
        with self._lock:
            self._sessions.pop(session_id, None)
            # Also clean rotation mappings pointing to this session
            to_remove = [k for k, v in self._rotation_map.items() if v == session_id]
            for k in to_remove:
                self._rotation_map.pop(k, None)

    def update_role(self, session_id, new_role):
        with self._lock:
            if session_id in self._sessions:
                self._sessions[session_id]['role'] = new_role
                return True
            return False

store = SessionStore()

def get_current_session():
    session_id = request.cookies.get('session_id')
    if not session_id:
        return None, None
    session = store.get(session_id)
    if session is None:
        return None, None
    # Check session expiry (24 hours)
    if time.time() - session['created_at'] > 86400:
        store.invalidate(session_id)
        return None, None
    session['last_access'] = time.time()
    return session_id, session

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing credentials'}), 400

    # Simplified auth (in production, use proper password verification)
    username = data['username']
    password = data['password']

    # Demo users
    users = {
        'admin': {'password_hash': hashlib.sha256(b'admin_secret_pw').hexdigest(), 'role': 'admin'},
        'user1': {'password_hash': hashlib.sha256(b'user1_password').hexdigest(), 'role': 'user'},
    }

    user = users.get(username)
    if not user:
        return jsonify({'error': 'Invalid credentials'}), 401

    provided_hash = hashlib.sha256(password.encode()).hexdigest()
    if not hmac.compare_digest(provided_hash, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    session_id = store.create(username, user['role'])
    resp = make_response(jsonify({'message': 'Login successful', 'role': user['role']}))
    resp.set_cookie('session_id', session_id, httponly=True, samesite='Strict')
    return resp

@app.route('/rotate-session', methods=['POST'])
def rotate_session():
    """Security best practice: rotate session ID periodically"""
    session_id, session = get_current_session()
    if session is None:
        return jsonify({'error': 'Not authenticated'}), 401

    new_session_id = store.rotate(session_id)
    if new_session_id is None:
        return jsonify({'error': 'Rotation failed'}), 500

    resp = make_response(jsonify({'message': 'Session rotated'}))
    resp.set_cookie('session_id', new_session_id, httponly=True, samesite='Strict')
    return resp

@app.route('/admin/promote', methods=['POST'])
def promote_user():
    """Admin endpoint to promote a user's session to admin role"""
    session_id, session = get_current_session()
    if session is None:
        return jsonify({'error': 'Not authenticated'}), 401
    if session.get('role') != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    data = request.get_json()
    target_session = data.get('target_session_id')
    if not target_session:
        return jsonify({'error': 'Missing target_session_id'}), 400

    if store.update_role(target_session, 'admin'):
        return jsonify({'message': 'User promoted'})
    return jsonify({'error': 'Session not found'}), 404

